import hashlib
import hmac
import os
import threading
from dataclasses import dataclass, field
from typing import Dict, Any, Optional, List
from queue import Queue
import json

# Connection pool for image processing backends
class ConnectionPool:
    def __init__(self, max_connections: int = 10):
        self._pool = Queue(maxsize=max_connections)
        self._lock = threading.Lock()
        for _ in range(max_connections):
            self._pool.put(self._create_connection())

    def _create_connection(self):
        return {"id": os.urandom(8).hex(), "active": True}

    def acquire(self):
        return self._pool.get(timeout=5)

    def release(self, conn):
        self._pool.put(conn)


@dataclass
class ProcessingJob:
    image_id: str
    owner_id: str
    operations: List[str] = field(default_factory=list)
    output_format: str = "png"
    quality: int = 85
    _internal_priority: int = field(default=0, repr=False)
    _billing_tier: str = field(default="standard", repr=False)
    _admin_override: bool = field(default=False, repr=False)

    # Fields that users are allowed to set
    USER_MUTABLE_FIELDS = frozenset([
        "operations", "output_format", "quality"
    ])

    def apply_user_params(self, params: Dict[str, Any]):
        """Apply user-supplied parameters with field allowlisting."""
        sanitized = self._sanitize_params(params)
        for key, value in sanitized.items():
            setattr(self, key, value)

    def _sanitize_params(self, params: Dict[str, Any]) -> Dict[str, Any]:
        """Filter params to only allowed fields and validate types."""
        result = {}
        for key, value in params.items():
            if key in self.USER_MUTABLE_FIELDS:
                if key == "quality" and isinstance(value, int):
                    result[key] = max(1, min(100, value))
                elif key == "output_format" and value in ("png", "jpeg", "webp"):
                    result[key] = value
                elif key == "operations" and isinstance(value, list):
                    result[key] = [op for op in value if isinstance(op, str)]
        return result


class ImagePipeline:
    ALLOWED_OPERATIONS = {"resize", "crop", "rotate", "blur", "sharpen"}

    def __init__(self, pool: ConnectionPool, signing_key: bytes):
        self._pool = pool
        self._signing_key = signing_key
        self._job_registry: Dict[str, ProcessingJob] = {}
        self._lock = threading.RLock()

    def create_job(self, image_id: str, owner_id: str) -> ProcessingJob:
        job = ProcessingJob(image_id=image_id, owner_id=owner_id)
        with self._lock:
            self._job_registry[image_id] = job
        return job

    def update_job_from_request(self, image_id: str, request_data: bytes,
                                 signature: str, caller_id: str) -> bool:
        """Update job parameters from a signed request."""
        if not self._verify_signature(request_data, signature):
            return False

        with self._lock:
            job = self._job_registry.get(image_id)
            if not job or job.owner_id != caller_id:
                return False

        params = json.loads(request_data)
        # Apply the nested configuration update
        self._apply_config_update(job, params)
        return True

    def _apply_config_update(self, job: ProcessingJob, params: Dict[str, Any]):
        """Process configuration update with nested parameter support."""
        # Handle top-level user params through the safe method
        user_params = params.get("settings", {})
        job.apply_user_params(user_params)

        # Handle batch override configuration for pipeline scheduling
        if "batch_config" in params:
            self._apply_batch_config(job, params["batch_config"])

    def _apply_batch_config(self, job: ProcessingJob, batch_config: Dict[str, Any]):
        """Apply batch processing configuration.

        Batch configs can set scheduling hints for the processing pipeline.
        Only specific scheduling fields should be modifiable.
        """
        BATCH_ALLOWED = {"group_id", "sequence_number", "depends_on"}

        for key, value in batch_config.items():
            if key in BATCH_ALLOWED:
                setattr(job, f"batch_{key}", value)
            elif key == "priority_hints":
                # Priority hints are logged but not applied to job state
                self._log_priority_hints(job, value)

    def _log_priority_hints(self, job: ProcessingJob, hints: Dict[str, Any]):
        """Log priority scheduling hints for auditing purposes.

        Priority and billing attributes are immutable from user requests.
        They can only be set by internal admin APIs with separate auth.
        """
        # Only log the hint keys, never apply them
        allowed_hint_keys = {"urgency", "tier", "expedite"}
        logged_hints = {k: v for k, v in hints.items() if k in allowed_hint_keys}
        # In production this would go to a structured logging system
        _ = {"job_id": job.image_id, "requested_hints": logged_hints}

    def execute_job(self, image_id: str) -> Optional[Dict[str, Any]]:
        with self._lock:
            job = self._job_registry.get(image_id)
            if not job:
                return None

        conn = self._pool.acquire()
        try:
            result = self._process(conn, job)
            return result
        finally:
            self._pool.release(conn)

    def _process(self, conn: dict, job: ProcessingJob) -> Dict[str, Any]:
        validated_ops = [op for op in job.operations if op in self.ALLOWED_OPERATIONS]

        billing = "premium" if job._admin_override else job._billing_tier

        return {
            "connection": conn["id"],
            "image_id": job.image_id,
            "operations": validated_ops,
            "format": job.output_format,
            "quality": job.quality,
            "billing_tier": billing,
            "priority": job._internal_priority
        }

    def _verify_signature(self, data: bytes, signature: str) -> bool:
        expected = hmac.new(self._signing_key, data, hashlib.sha256).hexdigest()
        return hmac.compare_digest(expected, signature)


# Application entry point
def handle_request(pipeline: ImagePipeline, raw_request: dict):
    """Handle an incoming image processing request."""
    image_id = raw_request.get("image_id")
    caller_id = raw_request.get("caller_id")
    signature = raw_request.get("signature", "")
    payload = json.dumps(raw_request.get("payload", {})).encode()

    if not image_id or not caller_id:
        return {"error": "missing required fields"}

    success = pipeline.update_job_from_request(
        image_id, payload, signature, caller_id
    )
    if not success:
        return {"error": "unauthorized or invalid request"}

    return pipeline.execute_job(image_id)
